import string
from typing import List

CSRF_CHARS = set(string.ascii_lowercase + string.digits)

def requestParser(validAuthTokens: List[str], requests: List[List[str]]) -> List[str]:
    valid = set(validAuthTokens)
    out = []
    for method, url in requests:
        _, sep, query = url.partition("?")
        params = []
        if sep:
            for part in query.split("&"):
                if "=" in part:
                    params.append(tuple(part.split("=", 1)))
        lookup = dict(params)
        ok = lookup.get("token") in valid
        if ok and method == "POST":
            csrf = lookup.get("csrf", "")
            ok = len(csrf) >= 8 and set(csrf) <= CSRF_CHARS
        if not ok:
            out.append("INVALID")
            continue
        fields = ["VALID"]
        for k, v in params:
            if k not in ("token", "csrf"):
                fields += [k, v]
        out.append(",".join(fields))
    return out
